 const d=await draftById(req.params.id,c);assertVersion(d,req.body.version);const reason=String(req.body.reason||'').trim(),replacement_id=String(req.body.replacement_draft_id||'');if(!reason||reason.length>500)throw fail(422,'Give a short reason for closing the interrupted draft.');if(d.state==='superseded'){if(d.fields._superseded_by!==replacement_id||d.fields._superseded_reason!==reason)throw fail(409,'This draft was closed with different terms.');return {draft:d};}if(d.state!=='exception')throw fail(409,'Only an interrupted failed approval can be closed this way.');
