 if(!product||replacement.id===d.id||replacement.state!=='applied'||replacement.product_id!==product.id||revision!==`${replacement.id}:${replacement.applied_version}`||revision===d.fields._approved_source_revision)throw fail(409,'A newer applied update for this same product must be current before closing this draft.');
