app.get('/api/drafts/:id/preview',auth('owner'),wrap(async(req,res)=>{res.json(await locked(async c=>{const d=await draftById(req.params.id,c);const matches=(await catalog(true)).filter(p=>p.title.trim().toLowerCase()===d.fields.name?.trim().toLowerCase()&&p.metadata.unit===d.fields.unit);if(matches.length>1)throw fail(409,'More than one product matches. Review identity.');const p=matches[0];let before=0;if(p){const levels=(await engine('stock',{inventory_ids:[p.variants[0].inventory_items[0].inventory_item_id],location_id:(await settings()).location_id})).levels;before=Number(levels[0]?.stocked_quantity||0)}return {version:d.version,product_id:p?.id||null,source_revision:p?`${p.metadata.source_draft}:${p.metadata.applied_version}`:null,before_quantity:before,target_quantity:Number.isSafeInteger(d.fields.quantity)?(d.fields.stock_action==='receipt'?before+d.fields.quantity:d.fields.stock_action==='recount'?d.fields.quantity:null):null,before_price_minor:p?.metadata.price_minor||null,price_minor:d.fields.price_minor??null};}))}));
