async function applyDraft(draftId,version,actor,review){return locked(async c=>{let d=await draftById(draftId,c);assertVersion(d,version);if(d.state==='applied'&&d.applied_version===version)return d;if(['rejected','superseded'].includes(d.state))throw fail(409,'This draft is closed. Start a new update.');if(contextPhoto(d))throw fail(422,'This is a store overview, not a product image. Start a new update with a close product photo.');if(d.photos?.length>1&&d.fields._primary_photo_index===undefined)throw fail(422,'Choose this product’s primary photo before approval.');validateFields(d.fields);productDetails(d.fields);if(d.fields.tax_class!=='exempt_unprepared_food')throw fail(422,'Tax classification must be confirmed.');const s=await settings();const products=await catalog(true);const matches=products.filter(p=>p.title.trim().toLowerCase()===d.fields.name.trim().toLowerCase()&&p.metadata.unit===d.fields.unit);if(matches.length>1)throw fail(409,'More than one product matches. Review identity before applying.');const existing=matches[0];if(existing&&(await c.query("SELECT id FROM avo.scheduled_specials WHERE state IN ('published','applying','exception') AND fields->>'product_id'=$1 AND (fields->>'ends_at')::timestamptz>now()",[existing.id])).rowCount)throw fail(409,'Close the scheduled special before changing this product.');assertSpecialSource(d.fields,existing);if(existing?.metadata?.kind==='box')throw fail(422,'Use the box offer controls to revise a box recipe.');if(!d.photo&&!existing?.thumbnail)throw fail(422,'Add a real product photo before publishing this item.');let before=0;if(existing){const inventoryId=existing.variants[0].inventory_items[0].inventory_item_id;const r=await engine('stock',{inventory_ids:[inventoryId],location_id:s.location_id});before=Number(r.levels[0]?.stocked_quantity||0)}if(review&&d.fields._approved_target===undefined&&(review.version!==d.version||review.product_id!==(existing?.id||null)||review.before_quantity!==before||review.source_revision!==(existing?`${existing.metadata.source_draft}:${existing.metadata.applied_version}`:null)))throw fail(409,'The product or stock changed since review. Refresh the comparison before approving.');const target=d.fields._approved_target??(d.fields.stock_action==='receipt'?before+d.fields.quantity:d.fields.quantity);if(d.fields._approved_target!==undefined&&d.fields._approved_before===undefined)throw fail(409,'This older interrupted approval needs a new reviewed update before stock can change.');const f={...d.fields,_approved_target:target,_approved_before:d.fields._approved_before??before,_approved_source_revision:d.fields._approved_source_revision??(existing?`${existing.metadata.source_draft}:${existing.metadata.applied_version}`:null),_existing_product_id:existing?.id};await c.query("UPDATE avo.drafts SET state='applying',fields=$2,last_error=NULL WHERE id=$1",[d.id,JSON.stringify(f)]);try{const result=await engine('apply',{...s,draft_id:d.id,version,fields:f,photo:d.photo,target_quantity:target});await c.query('INSERT INTO avo.audit(id,actor,action,subject,before_data,after_data,event_id) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(event_id) DO NOTHING',[id(),actor,'approve_product',d.id,JSON.stringify({quantity:before}),JSON.stringify(result),`approval_${d.id}_${version}`]);await c.query("UPDATE avo.drafts SET state='applied',product_id=$2,variant_id=$3,inventory_id=$4,applied_version=$5,updated_at=now() WHERE id=$1",[d.id,result.product_id,result.variant_id,result.inventory_id,version]);return draftById(d.id,c)}catch(e){await c.query("UPDATE avo.drafts SET state='exception',last_error=$2 WHERE id=$1",[d.id,String(e.message).slice(0,500)]);throw e}})}
// First checkout refuses unconfirmed product tax classes and all non-pickup fulfillment.
app.post('/api/checkout',auth(),wrap(async(req,res)=>{const r=await locked(async c=>{const ordering=(await c.query("SELECT value FROM avo.settings WHERE key='ordering'")).rows[0]?.value;if(ordering?.paused)throw fail(409,'Online ordering is paused. Existing orders remain available.');const {items,email,slot_id,nonce}=req.body||{};if(typeof nonce!=='string'||! /^[a-zA-Z0-9_-]{8,100}$/.test(nonce))throw fail(422,'Checkout purchase reference is required.');if(req.body.fulfillment&&req.body.fulfillment!=='pickup')throw fail(422,'Only local pickup is available.');if(!Array.isArray(items)||!items.length||items.length>30||typeof email!=='string'||!/^\S+@\S+\.\S+$/.test(email))throw fail(422,'Choose products and enter a valid email.');const revision=hash(JSON.stringify({nonce,session:req.user.session}));const prior=await c.query('SELECT * FROM avo.attempts WHERE revision=$1',[revision]);if(prior.rowCount){const a=prior.rows[0];if(!samePurchaseItems(a.snapshot.items,items)||a.snapshot.email!==email||a.slot_id!==slot_id)throw fail(409,'The basket changed. Start a new checkout.');if(a.state==='creating'){if(new Date(a.expires_at)<new Date())throw fail(409,'That checkout expired. Start a new one.');const prepared=await prepareAttempt(a,c);return {attempt_id:a.id,reference:a.id.slice(0,8),url:prepared.url,state:'pending'};}if(!['pending','paid'].includes(a.state))throw fail(409,'That checkout is closed. Start a new one.');return {attempt_id:a.id,reference:a.id.slice(0,8),url:a.snapshot.url,state:a.state};}const products=await catalog(),normalized=[];const seen=new Set();for(const item of items){if(seen.has(item.product_id))throw fail(422,'Duplicate basket lines are not allowed');seen.add(item.product_id);const p=products.find(p=>p.id===item.product_id);if(!p||p.metadata?.tax_class!=='exempt_unprepared_food'||!Number.isSafeInteger(item.quantity)||item.quantity<1||item.quantity>99)throw fail(422,'A basket item is unavailable or its quantity is invalid.');try{normalized.push(catalogItem(p,item))}catch(e){throw fail(422,e.message)}}const sr=await c.query('SELECT * FROM avo.slots WHERE id=$1 AND active AND cutoff>now()',[slot_id]);if(!sr.rowCount)throw fail(409,'That pickup window is no longer available.');const slot=sr.rows[0];const usage=await c.query("SELECT count(*) FROM avo.attempts WHERE slot_id=$1 AND state IN ('creating','pending','paid','completing') AND NOT EXISTS(SELECT 1 FROM avo.tasks t WHERE t.attempt_id=avo.attempts.id AND t.state='refunded')",[slot_id]);if(Number(usage.rows[0].count)>=slot.capacity)throw fail(409,'That pickup window is full.');const quoteTotal=normalized.reduce((sum,i)=>sum+i.price_minor*i.quantity,0);if(req.body.expected_total_minor!==undefined&&req.body.expected_total_minor!==quoteTotal)throw fail(409,'The basket price changed. Refresh the basket and review the new total before checkout.');const s=await settings(),attemptId=id();const snapshot={items:normalized,email,pickup_label:slot.label,total_minor:normalized.reduce((a,i)=>a+i.price_minor*i.quantity,0),currency:'USD',tax_minor:0};const holdMap=new Map();for(const item of normalized)for(const component of item.components)holdMap.set(component.inventory_id,(holdMap.get(component.inventory_id)||0)+component.quantity*item.quantity);const reservations=[...holdMap].map(([inventory_id,quantity])=>({inventory_id,quantity}));const levels=(await engine('stock',{inventory_ids:reservations.map(r=>r.inventory_id),location_id:s.location_id})).levels;for(const hold of reservations){const buffer=(await c.query('SELECT value FROM avo.settings WHERE key=$1',['safety_buffer:'+hold.inventory_id])).rows[0]?.value?.units||0;const level=levels.find(l=>l.inventory_item_id===hold.inventory_id);if(!level||hold.quantity>bufferAvailable(level,buffer))throw fail(409,'Not enough online stock is available for this basket. Review quantities.');}await c.query("INSERT INTO avo.attempts(id,cart_id,revision,slot_id,state,snapshot,expires_at,owner_session) VALUES($1,'creating',$2,$3,'creating',$4,$5,$6)",[attemptId,revision,slot_id,JSON.stringify({...snapshot,reservations}),new Date(Date.now()+1800000),req.user.session]);let prepared;try{prepared=await prepareAttempt({id:attemptId,snapshot:{...snapshot,reservations}},c)}catch(e){await c.query('UPDATE avo.attempts SET last_error=$2 WHERE id=$1',[attemptId,String(e.message).slice(0,500)]);throw e;}return {attempt_id:attemptId,reference:attemptId.slice(0,8),url:prepared.url}});res.json(r)}));
async function prepareAttempt(a,c){const prepared=await engine('checkout',{...(await settings()),items:a.snapshot.items,reservations:a.snapshot.reservations,email:a.snapshot.email,attempt_id:a.id,snapshot:a.snapshot});await c.query("UPDATE avo.attempts SET state='pending',last_error=NULL WHERE id=$1",[a.id]);return prepared;}
async function providerState(a,c=db){
 if(paymentMode==='simulator'){const event=await c.query("SELECT 1 FROM avo.events WHERE id=$1 AND provider='simulator' AND payload->>'status'='paid'",['sim_paid_'+a.id]);if(event.rowCount)return 'paid';const closedSession=a.payment_collection_id?(await c.query("SELECT 1 FROM public.payment_session WHERE payment_collection_id=$1 AND status='canceled' AND data->>'attempt_id'=$2 LIMIT 1",[a.payment_collection_id,a.id])).rowCount:false;return closedSession||new Date(a.expires_at)<new Date()?'expired':'pending'}
 const session=await stripe.checkout.sessions.retrieve(a.provider_session);if(session.livemode||session.metadata?.attempt_id!==a.id||session.amount_total!==a.snapshot.total_minor||session.currency!=='usd')throw fail(409,'Verified provider checkout does not match the frozen order.');return session.payment_status==='paid'?'paid':session.status==='expired'?'expired':'pending';
}
async function completeAttempt(a,c){
 if(a.state==='paid'){await c.query('INSERT INTO avo.tasks(id,order_id,attempt_id) VALUES($1,$2,$3) ON CONFLICT(order_id) DO NOTHING',[id(),a.order_id,a.id]);await c.query('UPDATE avo.attempts SET last_error=NULL WHERE id=$1',[a.id]);return {state:'paid',reference:a.id.slice(0,8),order_id:a.order_id};}
 if(!['pending','completing','exception'].includes(a.state))throw fail(409,'Checkout is closed.');if(await providerState(a,c)!=='paid')throw fail(409,'Payment has not been verified.');
 await c.query("UPDATE avo.attempts SET state='completing' WHERE id=$1",[a.id]);
 try{const done=await engine('complete',{cart_id:a.cart_id,reservation_ids:a.snapshot.reservation_ids});await c.query('BEGIN');try{await c.query("UPDATE avo.attempts SET state='paid',order_id=$2,last_error=NULL WHERE id=$1",[a.id,done.order.id]);await c.query('INSERT INTO avo.tasks(id,order_id,attempt_id) VALUES($1,$2,$3) ON CONFLICT(order_id) DO NOTHING',[id(),done.order.id,a.id]);await c.query('COMMIT')}catch(e){await c.query('ROLLBACK');throw e}return {state:'paid',reference:a.id.slice(0,8),order_id:done.order.id};}catch(e){await c.query("UPDATE avo.attempts SET state='exception',last_error=$2 WHERE id=$1",[a.id,String(e.message).slice(0,500)]);throw e;}
}
app.post('/api/simulate-payment',auth(),wrap(async(req,res)=>{if(paymentMode!=='simulator')throw fail(403,'Simulator is disabled');res.json(await locked(async c=>{const r=await c.query('SELECT * FROM avo.attempts WHERE id=$1',[req.body.attempt_id]);if(!r.rowCount)throw fail(404,'Checkout not found');const a=r.rows[0];if(a.owner_session!==req.user.session&&req.user.role!=='owner')throw fail(403,'This is another customer’s checkout.');if(['canceled','expired','payment_review','late_refund_pending','late_refunded'].includes(a.state))throw fail(409,'Checkout is closed. Start a new one.');if(a.state!=='paid'&&new Date(a.expires_at)<new Date())throw fail(409,'Checkout expired. Start a new one.');await c.query("INSERT INTO avo.events(id,provider,payload) VALUES($1,'simulator',$2) ON CONFLICT DO NOTHING",['sim_paid_'+a.id,JSON.stringify({status:'paid',attempt_id:a.id})]);return completeAttempt(a,c)}))}));
