app.get('/api/activity',auth('owner'),wrap(async(req,res)=>{const rows=(await db.query("SELECT a.id,a.actor,a.action,a.subject,a.before_data,a.after_data,a.created_at,coalesce(d.fields->>'name',b.name) AS subject_name FROM avo.audit a LEFT JOIN avo.drafts d ON d.id=a.subject LEFT JOIN avo.boxes b ON b.id=a.subject ORDER BY a.created_at DESC,a.id DESC LIMIT 30")).rows;const products=await catalog(true);const events=rows.map(row=>({...row,subject_name:row.subject_name||products.find(p=>p.id===row.subject||p.metadata.source_draft===row.subject)?.title||null}));res.json({events});}));
app.get('/api/exceptions',auth('owner'),wrap(async(req,res)=>{const attempts=(await db.query("SELECT id,state,last_error,created_at,snapshot->>'total_minor' AS total_minor,snapshot->>'late_refund_reason' AS late_refund_reason FROM avo.attempts WHERE last_error IS NOT NULL OR state='exception' ORDER BY created_at DESC LIMIT 50")).rows;const movements=(await db.query("SELECT id,event_id,product_id,action,quantity,reason,corrects_movement_id,state,last_error,created_at FROM avo.movements WHERE state='exception' ORDER BY created_at DESC LIMIT 50")).rows;const drafts=(await db.query("SELECT id,version,state,last_error,updated_at FROM avo.drafts WHERE state='exception' ORDER BY updated_at DESC LIMIT 50")).rows;res.json({attempts,movements,drafts})}));
app.post('/api/reconcile',auth('owner'),wrap(async(req,res)=>{await reconcile();await db.query('INSERT INTO avo.audit(id,actor,action,subject,after_data) VALUES($1,$2,$3,$4,$5)',[id(),'owner','request_reconciliation','checkout',JSON.stringify({provider_truth_checked:true})]);res.json({ok:true})}));
app.post('/api/marketing-drafts',auth('owner'),wrap(async(req,res)=>{res.json(await locked(async c=>{const {product_id,event_id}=req.body||{};if(typeof event_id!=='string'||!/^[a-zA-Z0-9_-]{8,100}$/.test(event_id))throw fail(422,'A source reference is required.');const previous=(await c.query('SELECT * FROM avo.marketing_drafts WHERE event_id=$1',[event_id])).rows[0];if(previous){if(previous.product_id!==product_id)throw fail(409,'This reference belongs to another product.');return {draft:previous};}const product=(await catalog()).find(p=>p.id===product_id);if(!product)throw fail(422,'Choose an approved product currently offered in the store.');const fields=productAnnouncement(product),draft=(await c.query('INSERT INTO avo.marketing_drafts(id,event_id,product_id,fields,actor) VALUES($1,$2,$3,$4,$5) RETURNING *',[id(),event_id,product.id,JSON.stringify(fields),'owner'])).rows[0];return {draft};}))}));
scheduledSpecialRoutes({app,auth,wrap,locked,db,catalog,engine,settings,assertVersion});
app.get('/api/health',(req,res)=>res.json({ok:true,mode:paymentMode}));app.use((err,req,res,next)=>{if(err instanceof multer.MulterError)return res.status(413).json({error:'Use up to six photos, each no larger than 8 MB.'});console.error('Request failed:',err.status||500,err.message);res.status(err.status||500).json({error:err.status?err.message:'The update could not be completed. Nothing is shown as saved until verified.'})});
app.listen(3200,'127.0.0.1',()=>console.log('Private command gateway ready on loopback:3200'));
export {app,applyDraft};
